@php
    $case = $maintenanceCase;
    $statusLabels = [
        'open' => 'باز', 'in_progress' => 'در حال تعمیر', 'submitted' => 'ارسال‌شده برای بررسی',
        'returned' => 'بازگشت برای اصلاح', 'completed' => 'تکمیل‌شده',
    ];
    $operationStatusLabels = [
        'draft' => 'پیش‌نویس', 'need_revision' => 'نیازمند اصلاح', 'submitOperation' => 'در انتظار بررسی',
        'approved' => 'تأییدشده', 'rejected' => 'ردشده',
    ];
    $status = $statusLabels[$case->status] ?? $case->status;
    $operations = $case->operations->filter(fn ($operation) => ! $operation->trashed());
    $beforePhoto = $case->photos->whereNull('operation_id')->firstWhere('type', 'before');
    $afterPhoto = $case->photos->whereNull('operation_id')->firstWhere('type', 'after');
    $materialsSummary = $operations->flatMap->operationMaterial->groupBy('id')->map(fn ($items) => [
        'title' => $items->first()->title,
        'unit' => $items->first()->unit,
        'qty' => $items->sum(fn ($material) => (float) $material->pivot->qty),
        'operations' => $items->pluck('pivot.operation_id')->unique()->values(),
    ])->values();
    $workflowStage = match ($case->status) { 'open' => 1, 'in_progress', 'returned' => 2, 'submitted' => 4, 'completed' => 5, default => 1 };
    $workflowSteps = ['نشانه‌گذاری', 'تعمیرات', 'ارسال برای تأیید', 'بررسی', 'تکمیل'];
    $faCount = fn ($value) => number_format((int) $value, 0, '.', ',');
@endphp

