ed-case .ec-sticky{position:sticky;bottom:14px;z-index:3;display:flex;flex-wrap:wrap;justify-content:space-between;gap:10px;margin-top:18px;padding:11px 13px;border:1px solid #d5deed;border-radius:15px;background:#ffffffed;box-shadow:0 12px 30px #1b315d1c}.embedded-case .ec-empty{padding:22px;text-align:center;border:1px dashed #cfd6e3;border-radius:14px;color:var(--ec-muted);background:var(--ec-soft)}
