<script>
(() => {
    const root = document.querySelector('#embedded-maintenance-case[data-case-id="{{ $case->id }}"]');
    if (!root || root.dataset.bound === '1') return;
    root.dataset.bound = '1';
    const token = document.querySelector('meta[name="csrf-token"]')?.content;
    root.querySelectorAll('.ec-photo-input').forEach(input => input.addEventListener('change', async () => {
        if (!input.files?.length) return; input.disabled = true;
        const body = new FormData(); body.append('photo', input.files[0]);
        try { const response = await fetch(input.dataset.url, {method:'POST', headers:{'Accept':'application/json','X-CSRF-TOKEN':token}, body}); if (!response.ok) throw new Error('ثبت تصویر انجام نشد.'); window.location.reload(); } catch (error) { window.alert(error.message || 'خطا در ثبت تصویر.'); input.disabled = false; }
    }));
    root.querySelector('.ec-submit')?.addEventListener('click', async event => { const button = event.currentTarget; if (!window.confirm('عملیات فعال برای تأیید ارسال شوند؟')) return; button.disabled = true; try { const response = await fetch(button.dataset.url, {method:'POST', headers:{'Accept':'application/json','X-CSRF-TOKEN':token}}); const result = await response.json().catch(() => ({})); if (!response.ok) { const details = Object.values(result.errors || {}).flat().join(' '); throw new Error(result.message || details || 'ارسال پرونده انجام نشد.'); } window.location.reload(); } catch (error) { let feedback = root.querySelector('[data-case-feedback]'); if (!feedback) { feedback = document.createElement('div'); feedback.dataset.caseFeedback = '1'; feedback.className = 'alert alert-danger mt-2 mb-0'; button.parentElement?.append(feedback); } feedback.textContent = error.message || 'ارسال پرونده انجام نشد.'; button.disabled = false; } });
    root.querySelectorAll('.ec-review').forEach(button => button.addEventListener('click', async () => { const comment = button.dataset.decision === 'returned' ? (window.prompt('دلیل بازگشت برای اصلاح را وارد کنید:') || '') : ''; if (button.dataset.decision === 'returned' && !comment) return; button.disabled = true; const response = await fetch(button.dataset.url, {method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':token},body:JSON.stringify({operation_id:Number(button.dataset.operationId),decision:button.dataset.decision,comment})}); if (response.ok) window.location.reload(); else { window.alert('ثبت تصمیم انجام نشد.'); button.disabled = false; } }));
})();
</script>
